const ageVerification=document.getElementById("common-age-verification"),agreeButton=document.getElementById("common-age-verification-agree");function closeAgeVerificationView(){ageVerification.parentNode.removeChild(ageVerification),document.scrollingElement.scrollTop=0}function isReferrerFromDmmGames(){const e=document.referrer,t=/^https?:\/\/([a-zA-Z0-9-]+\.)?games\.dmm\.co\.jp(\/|$)/;return t.test(e)}function hasAgeCheckOkParameter(){const e=new URLSearchParams(window.location.search);return e.get("ageCheck")==="ok"}function checkAgeVerificationNecessary(e){if(!e)return;try{if(isReferrerFromDmmGames()||hasAgeCheckOkParameter()){closeAgeVerificationView();return}}catch(e){console.error(e)}e.addEventListener("click",closeAgeVerificationView)}checkAgeVerificationNecessary(agreeButton),(()=>{const e=["Googlebot","Storebot-Google","Google-InspectionTool","GoogleOther","FeedFetcher-Google","Google-Read-Aloud","Google-Site-Verification","bingbot","duckduckbot","Bytespider","Linespider","facebook","Twitterbot","Lighthouse","Y!J-WSC","AdsBot-Google","AdsBot-Google-Mobile","Google-Safety","APIs-Google","Mediapartners-Google","Y!J-BRJ","Y!J-BRY","Y!J-BRZ","LY-SAD","adidxbot","MicrosoftPreview","BingVideoPreview"],t=navigator.userAgent.toLowerCase();e.some(e=>{if(t.indexOf(e.toLowerCase())!==-1)return closeAgeVerificationView(),!0})})()